import unittest
import mock
from mock import patch
from taf.ul.oam.selenium_coam.pages.panels.details import DetailPanel


class TestDetailPanel(unittest.TestCase):
    @patch('taf.ul.oam.selenium_coam.common.common.CustomWebdriver')
    def setUp(self, mock_driver):
        self.driver_obj = mock.MagicMock()
        mock_driver.return_value = self.driver_obj
        self.detail_panel = DetailPanel()

    def test_expand_details_panel(self):
        self.detail_panel.check_if_exists = mock.Mock(return_value=True)
        self.detail_panel.click_enabled_element = mock.Mock()

        self.detail_panel.expand_details_panel()
        self.detail_panel.click_enabled_element.assert_called()
